import React, { useState } from "react";
import SlideIndicator from "./SlideIndicator";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof SlideIndicator> = {
  id: "Components/SlideIndicator",
  title: "Components/Slide Indicator",
  component: SlideIndicator,
  args: {
    total: 6,
  },
  argTypes: {
    selected: {
      control: { disable: true },
      table: { disable: false },
    },
  },
};

export default meta;
type Story = StoryObj<typeof SlideIndicator>;

export const Basic: Story = {
  tags: ["visual-test"],
  parameters: { docs: { source: { type: "code" } } },
  render: (args) => {
    const [selected, setSelected] = useState(1);
    return (
      <SlideIndicator
        selected={selected}
        onStepClick={(_, index) => setSelected(index)}
        {...args}
      />
    );
  },
};

export const Vertical: Story = {
  render: () => {
    const [selected, setSelected] = useState(1);
    return (
      <SlideIndicator
        orientation="vertical"
        total={6}
        selected={selected}
        onStepClick={(_, index) => setSelected(index)}
      />
    );
  },
};

export const Overflow: Story = {
  render: () => {
    const [selected, setSelected] = useState(0);
    return (
      <SlideIndicator
        total={16}
        selected={selected}
        onStepClick={(_, index) => setSelected(index)}
      />
    );
  },
};

export const Dark: Story = {
  ...Basic,
  tags: ["visual-test"],
  parameters: { docs: { source: { type: "dynamic" } } },
  decorators: [withDarkMode],
};
